// Get locale for language translation
var env = GetEnvironment();
var locale = env['locale'];

// Set varaibles for labels
var name = $feature["name"];

// Set variables for Earlying Voting hours of operation
var earlyStart = Date($feature.earlyDate_start);
var earlyEnd = Date($feature.earlyDate_end);
var earlyOpen = Time(8, 0, 0, 0);
var earlyClose = Time(17, 0, 0, 0);

// Set variables for emergency voting locations with extended hours of operation
var extendedMondayHours = [
  `Recorder's Main Office`,
  `Recorder's Country Club Office`,
  `City of Tucson - Ward 2 Office`
];

// Set variables for day one Emergency Voting hours of operation
var emergencyStartDate_1 = Date(2026, 06, 18);
var emergencyTimeStart_1 = Time(9, 0, 0, 0);
var emergencyTimeEnd_1 = Time(15, 0, 0, 0);

// Set variables day two Emergency Voting hours of operation
var emergencyStartDate_2 = Date(2026, 06, 20);
var emergencyTimeStart_2 = IIf(
  Includes(extendedMondayHours, $feature.name), 
  Time(8, 0, 0, 0), 
  Time(9, 0, 0, 0)
  );
var emergencyTimeEnd_2 = IIf(
  Includes(extendedMondayHours, $feature.name), 
  Time(17, 0, 0, 0), 
  Time(15, 0, 0, 0)
  );

// Set variables for Election Day hours of operation
var electionDay = Date(2026, 06, 21);
var electionDayOpen = Time(6, 0, 0, 0);
var electionDayClose = Time(19, 0, 0, 0);
var dayOfWeek = Weekday(Now());
var holiday = Date(2026, 06, 03) // Date of holiday with months starting at 0 (January) and ending at 11 (December) includes a timestamp of 12:00:00 AM PST

// Set variables for language translation
var earlyVotingLabel = IIf(locale != 'es', '(Open 8am-5pm)', '(Abierto de 8am a 5pm)');
var electionDayLabel = IIf(locale != 'es', '(Open 6am-7pm)', '(Abierto de 6am a 7pm)');
var emergencyLabel_1 = IIf(locale != 'es', '(Open 9am-3pm)', '(Abierto de 9am a 3pm)');
if (Includes(extendedMondayHours, $feature.name)) {
  var emergencyLabel_2 = IIf(locale != 'es', '(Open 8am-5pm)', '(Abierto de 8am a 5pm)')}
else {
   emergencyLabel_2 = emergencyLabel_1
  }
var closedLabel = IIf(locale != 'es', '', TextFormatting.NewLine + '(Cerrado)');

if (Now() > earlyStart && Now() < earlyEnd && Time() > earlyOpen && Time() < earlyClose && dayOfWeek != 0 && dayOfWeek != 6 && Today() != electionDay && Today() != holiday) {
  return name + TextFormatting.NewLine + earlyVotingLabel
  }
else if (DateOnly(Today()) == emergencyStartDate_1 && Time() > emergencyTimeStart_1 && Time() < emergencyTimeEnd_1) {
  return name + TextFormatting.NewLine + emergencyLabel_1
}
else if (DateOnly(Today()) == emergencyStartDate_2 && Time() > emergencyTimeStart_2 && Time() < emergencyTimeEnd_2) {
  return name + TextFormatting.NewLine + emergencyLabel_2
}
else if (DateOnly(Today()) == electionDay && Time() > electionDayOpen && Time() < electionDayClose) {
  return name + TextFormatting.NewLine + electionDayLabel
}
else {
  return name + closedLabel
}

