// Set variables for regular Earlying Voting hours of operation
var earlyStart = Date($feature.earlyDate_start); // Date function is formatted with months starting at 0 (January) and ending at 11 (December) and includes a timestamp of 12:00:00 AM
var earlyEnd = Date($feature.earlyDate_end); // Date is formatted with months starting at 0 (January) and ending at 11 (December) and includes a timestamp of 12:00:00 AM
var earlyOpen = Time(8, 0, 0, 0); // Time function is formatted as 8:00:00.00
var earlyClose = Time(17, 0, 0, 0); // Time function is formatted as 17:00:00.00

// Set variables for emergency voting locations with extended hours of operation on the Monday before Election Day
var extendedMondayHours = [
  `Recorder's Main Office`,
  `Recorder's Country Club Office`,
  `City of Tucson - Ward 2 Office`
];

// Set variables for extended close date on the last day of early voting
var earlyExtendDate = Date(2026, 9, 30); // Date function is formatted with months starting at 0 (January) and ending at 11 (December) and includes a timestamp of 12:00:00 AM
var earlyExtendTime = Time(19, 0, 0, 0); // Time function is formatted as 19:00:00.00

// Set variables for day one of Emergency Voting hours of operation
var emergencyStartDate_1 = Date(2026, 9, 31); // Date is formatted with months starting at 0 (January) and ending at 11 (December) and includes a timestamp of 12:00:00 AM
var emergencyTimeStart_1 = Time(9, 0, 0, 0); // All locations open at 9AM on Saturday Emergency Voting Day
var emergencyTimeEnd_1 = Time(15, 0, 0, 0); // All locations close at 3PM on Saturday Emergency Voting Day

// Set variables for day two of Emergency Voting hours of operation
var emergencyStartDate_2 = Date(2026, 10, 2); // Date is formatted with months starting at 0 (January) and ending at 11 (December) and includes a timestamp of 12:00:00 AM
var emergencyTimeStart_2 = IIf(
  Includes(extendedMondayHours, $feature.name), // Finds locations with extended Monday hours
  Time(8, 0, 0, 0), // Extended opening hour (8AM)
  Time(9, 0, 0, 0) // Regular opening hour (9AM)
  );
var emergencyTimeEnd_2 = IIf(
  Includes(extendedMondayHours, $feature.name), // Finds locations with extended Monday hours
  Time(17, 0, 0, 0), // Extended closing hour (5PM)
  Time(15, 0, 0, 0) // Regular closing hour (3PM)
  );

// Set variables for Election Day hours of operation
//var electionDay = Date(2026, 06, 21); // Date function is formatted with months starting at 0 (January) and ending at 11 (December) and includes a timestamp of 12:00:00 AM
var dayOfWeek = Weekday(Now()); // Weekday function returns a number from 0-6 corresponding to the day of the week, 0 being Sunday and 6 being Saturday
var holiday = Date(2026, 06, 03) // Date of holiday with months starting at 0 (January) and ending at 11 (December) includes a timestamp of 12:00:00 AM

if (Now() > earlyStart && Now() < earlyEnd && Time() > earlyOpen && Time() < earlyClose && dayOfWeek != 0 && dayOfWeek != 6 && Today() != holiday && DateOnly(Today()) != earlyExtendDate) {
  return "Open for Early Voting"
}
else if (DateOnly(Today()) == DateOnly(earlyExtendDate) && Time() > earlyOpen && Time() < earlyExtendTime) {
  return "Open Late for Early Voting"
}
else if (DateOnly(Today()) == DateOnly(emergencyStartDate_1) && Time() > emergencyTimeStart_1 && Time() < emergencyTimeEnd_1) {
  return "Open for Emergency Voting - Day 1"
}
else if (DateOnly(Today()) == DateOnly(emergencyStartDate_2) && Time() > emergencyTimeStart_2 && Time() < emergencyTimeEnd_2) {
  return "Open for Emergency Voting - Day 2"
}
else {
  return "Closed"
}

