expressionInfos.expression:
// Get locale
var env = GetEnvironment();
var locale = env['locale'];

// Set variables
var name = $feature.name;
var dateToday = DateOnly(Now());
var dropOffDate = DateOnly('30 July 2024', 'D MMMM Y');
var dropOffTitle = IIf(locale != 'es', name + ' (Ballot Drop-Off Only)', name + ' (Solo Entrega de Boletas)');

// Array of locations that are always drop-off only
var dropOffAllDays = [
  `Recorder's Eastside Office`
];
// Array of locations that are drop-off only on Election Day
var dropOffElectionDay = [
  `Recorder's Eastside Office`,
  `Recorder's Main Office`,
  `Recorder's Country Club Office`
];

// Declare function to format pop-up titles based on today's date
function dropOffOnly (n) {
  if (dateToday != dropOffDate) {
    if (Includes(dropOffAllDays, n)) {
      return dropOffTitle;
    } else {
      return n;
    }
  } else if (dateToday == dropOffDate) {
    if (Includes(dropOffElectionDay, n)) {
      return dropOffTitle;
    } else {
      return n;
    }
  }
}

// Return pop-up title
return dropOffOnly(name);

